async () => {
window.__ev=[]; for (const n of ['conversation_closed:agent_0x99','phone_call_answered:agent_0x99','phone_call_declined:agent_0x99','phone_call_missed:agent_0x99','global_variable_changed:start_debrief_cutscene','conversation_closed:closing_debrief_person','objective_task_completed:use_launch_device']) window.eventDispatcher.on(n, ()=>window.__ev.push(n+'@'+Math.round(performance.now()/100)/10)); return true;

}

async () => {
const c=window.phoneRinger.current(); return {room:window.gameState.currentRoom, cur:c&&{n:c.npcId,s:c.state}, q:window.phoneRinger.queueLength(), mg:window.MinigameFramework.currentMinigame&&window.MinigameFramework.currentMinigame.constructor.name, g:window.gameState.globalVariables.briefing_played};

}

async () => {
const c=window.phoneRinger.current(); const b=document.querySelector('.incoming-call'); return {ringer: c?{npc:c.npcId,state:c.state,knot:c.knot}:null, banner: b?b.innerText.replace(/\n+/g,' | '):null, pendingCb: JSON.stringify((window.phoneRinger.pendingCallbacks&&window.phoneRinger.pendingCallbacks())||null)};

}

